def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    my_hp = my_status.get('hp', 0)
    my_budget = my_status.get('budget', 0.0)

    alive_opps = [o for o in opponents_status.values() if o.get('alive', False)]
    if not alive_opps:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Use only yesterday previous_trace bid to infer the pressure band
    prev_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Baseline target: bid band that kept others alive (~110-116)
    # If someone previously bid very low and died, avoid that style.
    target = 112.0
    if prev_bids:
        highest_prev = max(prev_bids)
        lowest_prev = min(prev_bids)
        # If the room is bidding aggressively, match closer to the floor of their success.
        if highest_prev >= 115.0:
            target = 113.0
        elif lowest_prev <= 80.0:
            # Indicates riskier behavior exists; stay safer.
            target = 114.0
        else:
            # Moderate consensus; slightly undercut.
            target = 111.0

    # Supply pressure: when supply is scarce, increase bid to secure water.
    # supply is float; map to a discrete pressure level safely.
    span = float(MAX_SUPPLY - MIN_SUPPLY)
    if span <= 0:
        pressure = 0
    else:
        t = (float(supply) - float(MIN_SUPPLY)) / span
        if t < 0:
            t = 0.0
        if t > 1:
            t = 1.0
        # lower supply => higher pressure
        pressure = int((1.0 - t) * 2.0)  # 0..2

    # If my hp is low, bid more aggressively.
    hp_pressure = 0
    if my_hp <= 2:
        hp_pressure = 2
    elif my_hp <= 4:
        hp_pressure = 1

    # Compute final bid with conservative cap based on budget.
    # Keep under DAILY_SALARY most of the time to preserve budget, but allow spikes.
    bid = target
    bid += 6.0 * pressure
    bid += 10.0 * hp_pressure

    # If supply is extremely low, ensure we can actually win by going up near 120-125.
    if float(supply) <= float(WATER_REQ):
        bid = max(bid, 120.0)

    # Budget safety: never exceed what we can pay.
    # Also avoid overbidding when budget is low: scale down.
    if my_budget <= 0:
        return 0.0

    # If budget is tight, scale proportionally.
    if my_budget < bid:
        bid = my_budget

    # Ensure we don't bid trivially low when hp is decent.
    if my_hp >= 6 and bid < 95.0:
        bid = 95.0

    # Final clamp to a reasonable range for this meta-round.
    if bid < 0.0:
        bid = 0.0
    if bid > my_budget:
        bid = my_budget

    return float(bid)

