        my_current_bid = max(my_current_bid, DAILY_SALARY * 1.8)

    yesterday_bids = []
    desperate_opponents_exist = False
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

        if opp['hp'] <= 2 or opp['no_water_days'] >= 1:
            desperate_opponents_exist = True

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 1.0:
            if my_status['hp'] > 5:
                my_current_bid = min(my_current_bid, DAILY_SALARY * 0.4)
            else:
                my_current_bid = max(my_current_bid, highest_prev_bid + 5.0)

        elif highest_prev_bid >= DAILY_SALARY * 0.7:
            my_current_bid = max(my_current_bid, highest_prev_bid + 2.0)

        else:
            my_current_bid = min(my_current_bid, highest_prev_bid + 1.0)

    available_units = int(day_context['supply'] // WATER_REQ)
    num_active_players = len(alive_opponents) + 1

    if available_units < num_active_players and desperate_opponents_exist:
        if my_status['hp'] <= 4:
            my_current_bid = max(my_current_bid, DAILY_SALARY * 1.6)
        elif my_status['hp'] > 6 and days_remaining > 3:
            my_current_bid = min(my_current_bid, DAILY_SALARY * 0.5)
        else:
            my_current_bid = max(my_current_bid, DAILY_SALARY * 1.2)

    final_bid = min(my_status['budget'], my_current_bid)

    final_bid = max(1.0, final_bid)

    return final_bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25
    supply = int(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    yesterday_max_bid = 0.0
    if alive_opponents:
        bids = []
        for opp in alive_opponents:
            trace = opp.get('previous_trace', {})
            if trace and trace.get('bid') is not None:
                bids.append(trace['bid'])
        if bids:
            yesterday_max_bid = max(bids)
    scarcity = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY)
    base_factor = 0.5 + 0.3 * (day / 10.0) - 0.1 * (1 - scarcity)
    if hp <= 2:
        base_factor = min(base_factor + 0.3, 0.95)
    elif hp <= 4 and day >= 7:
        base_factor = min(base_factor + 0.2, 0.85)
    target = DAILY_SALARY * base_factor
    if yesterday_max_bid > DAILY_SALARY * 0.8 and hp > 3:
        target = min(target, DAILY_SALARY * 0.4)
    elif yesterday_max_bid > DAILY_SALARY * 0.95:
        target = max(target, DAILY_SALARY * 0.7)
    if budget < target:
        target = budget
    return target
